result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "numwords.py", "content": """"Number-to-words converter for integers 0-9999 in English and Spanish.

Rules (inline):

English:
  - 0-19 have fixed forms; tens 20-90 are fixed words.
  - Tens+units compounds are hyphenated: 'forty-two'.
  - Hundreds use '<n> hundred'; no 'and' anywhere ('one hundred five').

Spanish:
  - 0-29 fixed forms: cero..quince, dieciseis->dieciséis family,
    veinti- family with accents: veintiuno, veintidós, veintitrés,
    veinticuatro, veinticinco, veintiséis, ...
  - 31-99: '<tens> y <units>' pattern: 'treinta y uno', 'cuarenta y dos'.
  - 100 exactly is 'cien'; 101-199 use 'ciento' + rest.
  - Special hundreds: 500 quinientos, 700 setecientos, 900 novecientos.
  - Thousands: '<n> mil', never 'un mil': 1000 = 'mil uno' style
    (1000 alone = 'mil', 1001 = 'mil uno', 2000 = 'dos mil').
"""

_ONES_EN = [
    "zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
    "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
    "sixteen", "seventeen", "eighteen", "nineteen",
]

_TENS_EN = {
    2: "twenty", 3: "thirty", 4: "forty", 5: "fifty",
    6: "sixty", 7: "seventy", 8: "eighty", 9: "ninety",
}

_ONES_ES = [
    "cero", "uno", "dos", "tres", "cuatro", "cinco", "seis", "siete",
    "ocho", "nueve", "diez", "once", "doce", "trece", "catorce", "quince",
    "dieciséis", "diecisiete", "dieciocho", "diecinueve",
]

_TENS_ES = {
    2: "veinte", 3: "treinta", 4: "cuarenta", 5: "cincuenta",
    6: "sesenta", 7: "setenta", 8: "ochenta", 9: "noventa",
}

# Fixed forms 0-29 (dieciséis / veintidós families with accents).
_SPECIALS_ES = _ONES_ES + ["veinte", "veintiuno", "veintidós", "veintitrés",
                           "veinticuatro", "veinticinco", "veintiséis",
                           "veintisiete", "veintiocho", "veintinueve"]

# Special hundreds: 500, 700, 900.
_HUNDREDS_ES = {5: "quinientos", 7: "setecientos", 9: "novecientos"}


def _to_words_en(n):
    if n < 20:
        return _ONES_EN[n]
    if n < 100:
        t, u = divmod(n, 10)
        if u == 0:
            return _TENS_EN[t]
        # Hyphenated tens-units compound.
        return _TENS_EN[t] + "-" + _ONES_EN[u]
    if n < 1000:
        h, r = divmod(n, 100)
        base = _ONES_EN[h] + " hundred"
        return base if r == 0 else base + " " + _to_words_en(r)
    th, r = divmod(n, 1000)
    base = _ONES_EN[th] + " thousand"
    return base if r == 0 else base + " " + _to_words_en(r)


def _to_words_es(n):
    if n < 30:
        return _SPECIALS_ES[n]
    if n < 100:
        t, u = divmod(n, 10)
        if u == 0:
            return _TENS_ES[t]
        # 'treinta y uno' pattern.
        return _TENS_ES[t] + " y " + _ONES_ES[u]
    if n < 1000:
        h, r = divmod(n, 100)
        if h == 1:
            # 100 exactly is 'cien'; 101-199 use 'ciento'.
            if r == 0:
                return "cien"
            base = "ciento"
        else:
            base = _HUNDREDS_ES.get(h) or (_ONES_ES[h].rstrip("o") + "ientos"
                                           if False else None)
            if base is None:
                base = {"2": "doscientos", "3": "trescientos",
                        "4": "cuatrocientos", "6": "seiscientos",
                        "8": "ochocientos"}[str(h)]
        return base if r == 0 else base + " " + _to_words_es(r)
    th, r = divmod(n, 1000)
    # Never 'un mil': 1000 is just 'mil', 2000 'dos mil'.
    base = "mil" if th == 1 else _ONES_ES[th] + " mil"
    return base if r == 0 else base + " " + _to_words_es(r)


def to_words(n, lang):
    """Convert integer 0 <= n <= 9999 to words in lang ('en' or 'es')."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("n must be an integer")
    if not 0 <= n <= 9999:
        raise ValueError("n must be between 0 and 9999")
    if lang == "en":
        return _to_words_en(n)
    if lang == "es":
        return _to_words_es(n)
    raise ValueError("lang must be 'en' or 'es'")
